void config_kind(uint32_t i, channels::road_kind &g) {
  switch (i) {
    case 0: config_kind_alley(g); return;
    case 1: config_kind_boardwalk(g); return;
    case 2: config_kind_bridge(g); return;
    case 3: config_kind_drystone_way(g); return;
    case 4: config_kind_elven_way(g); return;
    case 5: config_kind_gate(g); return;
    case 6: config_kind_high_street(g); return;
    case 7: config_kind_lane(g); return;
    case 8: config_kind_market(g); return;
    case 9: config_kind_moss_path(g); return;
    case 10: config_kind_quay(g); return;
    case 11: config_kind_sand_lane(g); return;
    case 12: config_kind_square(g); return;
    case 13: config_kind_street(g); return;
  }
}

