int foundry_road_kind_find(const char *name) {
  static const char *const names[] = {"alley", "boardwalk", "bridge", "drystone_way", "elven_way", "gate", "high_street", "lane", "market", "moss_path", "quay", "sand_lane", "square", "street"};
  for (int i = 0; name && i < 14; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

